import { useState, useEffect, useRef } from 'react';
import './styles.css';
import Login from './Login';
import { useAuth } from './AuthContext';

function App() {
  // Get user from auth context
  const { currentUser, logout } = useAuth();
  
  const [songs, setSongs] = useState([]);
  const [currentSong, setCurrentSong] = useState(null);
  const [query, setQuery] = useState('eminem');
  const [input, setInput] = useState('');
  const [recentPlays, setRecentPlays] = useState([]);
  const [playlists, setPlaylists] = useState({});
  const [newPlaylistName, setNewPlaylistName] = useState('');
  const [activeTab, setActiveTab] = useState('results');
  const [showAddDialog, setShowAddDialog] = useState(null);
  const [darkMode, setDarkMode] = useState(false);
  const playerRef = useRef(null);

  // If user is not logged in, show login page
  if (!currentUser) {
    return <Login />;
  }

  const searchSongs = async (searchTerm) => {
    try {
      const response = await fetch(
        `https://deezerdevs-deezer.p.rapidapi.com/search?q=${searchTerm}`,
        {
          method: 'GET',
          headers: {
            'X-RapidAPI-Key': '3319ab7c91msh6b1b05141c68417p1783ffjsn6acb6efc6170',
            'X-RapidAPI-Host': 'deezerdevs-deezer.p.rapidapi.com'
          }
        }
      );
      const data = await response.json();
      setSongs(data.data);
    } catch (error) {
      console.error('Deezer API error:', error);
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (input.trim()) {
      setQuery(input.trim());
      searchSongs(input.trim());
      setInput('');
      setActiveTab('results');
    }
  };

  const handlePlay = (song) => {
    setCurrentSong(song);
    if (!recentPlays.find((s) => s.id === song.id)) {
      setRecentPlays((prev) => [song, ...prev.slice(0, 9)]);
    }
  };

  const handleAddToPlaylist = (playlistName, song) => {
    setPlaylists((prev) => {
      const updated = { ...prev };
      if (!updated[playlistName]) updated[playlistName] = [];
      if (!updated[playlistName].find((s) => s.id === song.id)) {
        updated[playlistName].push(song);
      }
      return updated;
    });
    setShowAddDialog(null);
  };

  const removeFromPlaylist = (playlistName, songId) => {
    setPlaylists((prev) => {
      const updated = { ...prev };
      updated[playlistName] = updated[playlistName].filter((s) => s.id !== songId);
      return updated;
    });
  };

  const createPlaylist = () => {
    if (newPlaylistName.trim() && !playlists[newPlaylistName]) {
      setPlaylists((prev) => ({ ...prev, [newPlaylistName]: [] }));
      setNewPlaylistName('');
    }
  };

  const toggleDarkMode = () => {
    setDarkMode(!darkMode);
  };

  // Handle logout
  const handleLogout = async () => {
    try {
      await logout();
    } catch (error) {
      console.error('Failed to log out', error);
    }
  };

  useEffect(() => {
    searchSongs(query);
  }, []);

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (playerRef.current && !playerRef.current.contains(e.target)) {
        setCurrentSong(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className={`app ${darkMode ? 'dark' : ''}`}>
      <div className="header">
        <img src="https://upload.wikimedia.org/wikipedia/commons/1/11/CSUF_Titans_Logo.svg" alt="CSUF Logo" className="logo" />
        <h1>Tuffy Music</h1>
        <div className="header-controls">
          <button className="dark-toggle" onClick={toggleDarkMode}>
            {darkMode ? '☀️ Light' : '🌙 Dark'}
          </button>
          <button className="logout-button" onClick={handleLogout}>
            Logout
          </button>
          <span className="user-email">{currentUser.email}</span>
        </div>
      </div>

      {activeTab === 'results' && (
        <form onSubmit={handleSubmit} className="search-bar">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Search for a song or artist..."
          />
          <button type="submit">Search</button>
        </form>
      )}

      <div className="tabs">
        <button className={activeTab === 'results' ? 'active' : ''} onClick={() => setActiveTab('results')}>🔍 Results</button>
        <button className={activeTab === 'playlist' ? 'active' : ''} onClick={() => setActiveTab('playlist')}>📂 Playlists</button>
        <button className={activeTab === 'recent' ? 'active' : ''} onClick={() => setActiveTab('recent')}>🕒 Recent</button>
      </div>

      {currentSong && (
        <div className={`player ${currentSong ? 'show' : ''}`} ref={playerRef}>
          <img src={currentSong.album.cover_medium} alt="album" />
          <div className="info">
            <h2>{currentSong.title}</h2>
            <h3>{currentSong.artist.name}</h3>
            <audio controls autoPlay src={currentSong.preview}>
              Your browser does not support the audio element.
            </audio>
          </div>
        </div>
      )}

      {activeTab === 'results' && (
        <>
          <h2>Results</h2>
          <div className="playlist">
            {songs.map((song) => (
              <div key={song.id} className="song">
                <img src={song.album.cover_medium} alt="album" onClick={() => handlePlay(song)} />
                <div className="song-info">
                  <p className="title">{song.title}</p>
                  <p className="artist">{song.artist.name}</p>
                  <button onClick={() => setShowAddDialog(song)}>Add to Playlist</button>
                </div>
              </div>
            ))}
          </div>
        </>
      )}

      {activeTab === 'playlist' && (
        <>
          <h2>Your Playlists</h2>
          <div className="create-playlist">
            <input
              type="text"
              value={newPlaylistName}
              onChange={(e) => setNewPlaylistName(e.target.value)}
              placeholder="New Playlist Name"
            />
            <button onClick={createPlaylist}>Create</button>
          </div>
          <div className="floating-playlists">
            {Object.keys(playlists).map((name) => (
              <div key={name} className="playlist-card">
                <h3>{name}</h3>
                {playlists[name].length === 0 ? (
                  <p>No songs yet</p>
                ) : (
                  playlists[name].map((song) => (
                    <div key={song.id} className="mini-song">
                      <img src={song.album.cover_small} alt="thumb" onClick={() => handlePlay(song)} />
                      <div>
                        <p>{song.title}</p>
                        <p className="small">{song.artist.name}</p>
                      </div>
                      <button className="remove" onClick={() => removeFromPlaylist(name, song.id)}>🗑️</button>
                    </div>
                  ))
                )}
              </div>
            ))}
          </div>
        </>
      )}

      {activeTab === 'recent' && (
        <>
          <h2>Recent Plays</h2>
          <div className="playlist">
            {recentPlays.map((song) => (
              <div key={song.id} className="song" onClick={() => handlePlay(song)}>
                <img src={song.album.cover_medium} alt="album" />
                <div className="song-info">
                  <p className="title">{song.title}</p>
                  <p className="artist">{song.artist.name}</p>
                </div>
              </div>
            ))}
          </div>
        </>
      )}

      {showAddDialog && (
        <div className="dialog">
          <h3>Add to Playlist</h3>
          {Object.keys(playlists).length === 0 && <p>No playlists available</p>}
          <ul>
            {Object.keys(playlists).map((name) => (
              <li key={name} onClick={() => handleAddToPlaylist(name, showAddDialog)}>
                {name}
              </li>
            ))}
          </ul>
          <button onClick={() => setShowAddDialog(null)}>Cancel</button>
        </div>
      )}
    </div>
  );
}

export default App;
